		public bool CheckCanPlayCommand(global::Dpr.SequenceEditor.CommandParam param) {
			if (param.IsAlreadyCalled)
				return false;

			if (param.EndTime + INVALID_COMMAND_OFFSET_END_TIME <= m_iPtrSequenceSystem.CurrentTime)
				return false;

			int value = -1;
			if (param.TryGetOptionValue(GRP_OPT.GRP_OPT_SPE_TRG_POKE, out value))
			{
				switch ((GRP_OPT_SPE_TRG_POKE)value)
				{
					case GRP_OPT_SPE_TRG_POKE.GRP_OPT_SPE_TRG1_PSV_NONE:
					{
						PokemonParam pokeParam = __GetPlayerData__((int)SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK)).pokemonInfo.pokeParam;
						if (pokeParam != null && (pokeParam.GetMonsNo() == MonsNo.PIKATYUU || pokeParam.GetMonsNo() == MonsNo.IIBUI || pokeParam.GetMonsNo() == MonsNo.NYAASU))
							return false;
						break;
					}

					case GRP_OPT_SPE_TRG_POKE.GRP_OPT_SPE_TRG1_PSV_PIKA_NOR:
					case GRP_OPT_SPE_TRG_POKE.GRP_OPT_SPE_TRG1_PSV_PIKA_G_NOR:
					{
						PokemonParam pokeParam = __GetPlayerData__((int)SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK)).pokemonInfo.pokeParam;
						if (pokeParam == null || pokeParam.GetMonsNo() != MonsNo.PIKATYUU || pokeParam.GetFormNo() != 0)
							return false;
						break;
					}

					case GRP_OPT_SPE_TRG_POKE.GRP_OPT_SPE_TRG1_PSV_PIKA_SATO:
					case GRP_OPT_SPE_TRG_POKE.GRP_OPT_SPE_TRG1_PSV_PIKA_G_SATO:
					{
						PokemonParam pokeParam = __GetPlayerData__((int)SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK)).pokemonInfo.pokeParam;
						if (pokeParam == null || pokeParam.GetMonsNo() != MonsNo.PIKATYUU || pokeParam.GetFormNo() == 0)
							return false;
						break;
					}

					case GRP_OPT_SPE_TRG_POKE.GRP_OPT_SPE_TRG1_PSV_PIKA_SP_G:
					{
						PokemonParam pokeParam = __GetPlayerData__((int)SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK)).pokemonInfo.pokeParam;
						if (pokeParam == null || pokeParam.GetMonsNo() != MonsNo.PIKATYUU)
							return false;
						break;
					}

					case GRP_OPT_SPE_TRG_POKE.GRP_OPT_SPE_TRG1_PSV_IIBUI_NOR:
					case GRP_OPT_SPE_TRG_POKE.GRP_OPT_SPE_TRG1_PSV_IIBUI_SP_G:
					case GRP_OPT_SPE_TRG_POKE.GRP_OPT_SPE_TRG1_PSV_IIBUI_G_NOR:
					{
						PokemonParam pokeParam = __GetPlayerData__((int)SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK)).pokemonInfo.pokeParam;
						if (pokeParam == null || pokeParam.GetMonsNo() != MonsNo.IIBUI)
							return false;
						break;
					}

					case GRP_OPT_SPE_TRG_POKE.GRP_OPT_SPE_TRG1_PSV_NYAASU_SP_G:
					{
						PokemonParam pokeParam = __GetPlayerData__((int)SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK)).pokemonInfo.pokeParam;
						if (pokeParam == null || pokeParam.GetMonsNo() != MonsNo.NYAASU)
							return false;
						break;
					}
				}
			}

			if (param.TryGetOptionValue(GRP_OPT.GRP_OPT_SPE_TRG_POKE_RARE, out value))
			{
				switch ((GRP_OPT_SPE_TRG_POKE_RARE)value)
				{
					case GRP_OPT_SPE_TRG_POKE_RARE.GRP_OPT_SPE_TRG1_POKE_RARE_NONE:
					{
						BtlvPos vpos = SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK);
						BOPokemon pokeModel = GetPokeModel(vpos);
						if (pokeModel)
						{
							PokemonParam pokeParam = __GetPlayerData__((int)vpos).pokemonInfo.pokeParam;
							bool fastMode = pokeParam.StartFastMode();
							RareType rareType = pokeParam.GetRareType();
							pokeParam.EndFastMode(fastMode);
							if (rareType != RareType.NOT_RARE)
								return false;
						}
						break;
					}

					case GRP_OPT_SPE_TRG_POKE_RARE.GRP_OPT_SPE_TRG1_POKE_RARE_A:
					{
						BtlvPos vpos = SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK);
						BOPokemon pokeModel = GetPokeModel(vpos);
						if (!pokeModel)
							return false;

						PokemonParam pokeParam = __GetPlayerData__((int)vpos).pokemonInfo.pokeParam;
						bool fastMode = pokeParam.StartFastMode();
						RareType rareType = pokeParam.GetRareType();
						pokeParam.EndFastMode(fastMode);
						if (rareType != RareType.CAPTURED)
							return false;
						break;
					}

					case GRP_OPT_SPE_TRG_POKE_RARE.GRP_OPT_SPE_TRG1_POKE_RARE_B:
					{
						BtlvPos vpos = SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_ATK);
						BOPokemon pokeModel = GetPokeModel(vpos);
						if (!pokeModel)
							return false;

						PokemonParam pokeParam = __GetPlayerData__((int)vpos).pokemonInfo.pokeParam;
						bool fastMode = pokeParam.StartFastMode();
						RareType rareType = pokeParam.GetRareType();
						pokeParam.EndFastMode(fastMode);
						if (rareType != RareType.DISTRIBUTED)
							return false;
						break;
					}

					case GRP_OPT_SPE_TRG_POKE_RARE.GRP_OPT_SPE_TRG2_POKE_RARE_NONE:
					{
						BtlvPos vpos = SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEF);
						BOPokemon pokeModel = GetPokeModel(vpos);
						if (pokeModel)
						{
							PokemonParam pokeParam = __GetPlayerData__((int)vpos).pokemonInfo.pokeParam;
							bool fastMode = pokeParam.StartFastMode();
							RareType rareType = pokeParam.GetRareType();
							pokeParam.EndFastMode(fastMode);
							if (rareType != RareType.NOT_RARE)
								return false;
						}
						break;
					}

					case GRP_OPT_SPE_TRG_POKE_RARE.GRP_OPT_SPE_TRG2_POKE_RARE_A:
					{
						BtlvPos vpos = SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEF);
						BOPokemon pokeModel = GetPokeModel(vpos);
						if (!pokeModel)
							return false;

						PokemonParam pokeParam = __GetPlayerData__((int)vpos).pokemonInfo.pokeParam;
						bool fastMode = pokeParam.StartFastMode();
						RareType rareType = pokeParam.GetRareType();
						pokeParam.EndFastMode(fastMode);
						if (rareType != RareType.CAPTURED)
							return false;
						break;
					}

					case GRP_OPT_SPE_TRG_POKE_RARE.GRP_OPT_SPE_TRG2_POKE_RARE_B:
					{
						BtlvPos vpos = SeqComFunc_GetTargetPoke(SEQ_DEF_POS.SEQ_DEF_POS_DEF);
						BOPokemon pokeModel = GetPokeModel(vpos);
						if (!pokeModel)
							return false;

						PokemonParam pokeParam = __GetPlayerData__((int)vpos).pokemonInfo.pokeParam;
						bool fastMode = pokeParam.StartFastMode();
						RareType rareType = pokeParam.GetRareType();
						pokeParam.EndFastMode(fastMode);
						if (rareType != RareType.DISTRIBUTED)
							return false;
