					}

					case GRP_OPT_SPE_TRG_POKE_RARE.GRP_OPT_SPE_TRG3_POKE_RARE_B:
					{
						BOPokemon pokeModel = GetPokeModel(BtlvPos.BTL_VPOS_NEAR_2);
						if (!(pokeModel && pokeModel.IsEnable))
							return false;

						PokemonParam pokeParam = __GetPlayerData__((int)BtlvPos.BTL_VPOS_NEAR_2).pokemonInfo.pokeParam;
