						pokeParam.EndFastMode(fastMode);
						if (rareType != RareType.DISTRIBUTED)
							return false;
						break;
					}
				}
			}

			if (param.TryGetOptionValue(GRP_OPT.GRP_OPT_POKE_SIZE, out value))
			{
				switch ((GRP_OPT_POKE_SIZE)value)
				{
					// Shipped mapping: ATK_L -> L, ATK_UNDER_M -> M, DEF_L -> S (01d7f2a4 / 01d7f2fc / 01d7f2d0).
					case GRP_OPT_POKE_SIZE.GRP_OPT_ATK_L:
						return __GetPlayerData__((int)ConvertPokeTrgTovPos(param.GetGroupOption(GRP_OPT.GRP_OPT_POKE_TRG).Value)).pokemonInfo.size == Size.L;

					case GRP_OPT_POKE_SIZE.GRP_OPT_ATK_UNDER_M:
						return __GetPlayerData__((int)ConvertPokeTrgTovPos(param.GetGroupOption(GRP_OPT.GRP_OPT_POKE_TRG).Value)).pokemonInfo.size == Size.M;

					case GRP_OPT_POKE_SIZE.GRP_OPT_DEF_L:
						return __GetPlayerData__((int)ConvertPokeTrgTovPos(param.GetGroupOption(GRP_OPT.GRP_OPT_POKE_TRG).Value)).pokemonInfo.size == Size.S;
