		private global::Dpr.Battle.Logic.BtlvPos ConvertPokeTrgTovPos(int value) {
			if (value >= 0x83 && value <= 0x85)
				return (BtlvPos)(value - 0x82);

			return BtlvPos.BTL_VPOS_NEAR_1;
		}
